message.content:
Review the following React component for performance and efficiency issues. Focus on:
1. **Unnecessary work on every render**: computations that should be memoized or moved to module scope
2. **Missing useMemo/useCallback**: derived values recalculated on every render
3. **Unnecessary re-renders**: state that could be avoided with CSS
4. **Memory leaks**: event listeners, intervals not cleaned up
5. **Redundant computations**: things computed multiple times

Here is the key section of `/home/runner/workspace/artifacts/courtbook/src/pages/home.tsx`:

Lines 285-435 (the Home() component setup):
```tsx
export default function Home() {
  const ALL_SPORTS = Object.keys(SPORT_LABELS);  // line 292 — recalculated every render
  const [activeSports, setActiveSports] = useState<Set<string>>(new Set(ALL_SPORTS));

  // 4 separate dropdown states + refs (lines 313-323):
  const [dropdownOpen, setDropdownOpen] = useState(false);
  const searchRef = useRef<HTMLDivElement>(null);
  const [cityDropdownOpen, setCityDropdownOpen] = useState(false);
  const cityRef = useRef<HTMLDivElement>(null);
  const [timeDropdownOpen, setTimeDropdownOpen] = useState(false);
  const timeRef = useRef<HTMLDivElement>(null);
  const [dateDropdownOpen, setDateDropdownOpen] = useState(false);
  const dateRef = useRef<HTMLDivElement>(null);

  // Time-of-day accent: interval fires every 60s (line 329-332)
  const [currentHour, setCurrentHour] = useState(() => new Date().getHours());
  useEffect(() => {
    const tick = setInterval(() => setCurrentHour(new Date().getHours()), 60_000);
    return () => clearInterval(tick);
  }, []);

  // contrastText() defined inline — new function object every render (line 351-354):
  function contrastText(hex: string) {
    const r = parseInt(hex.slice(1,3),16), g = parseInt(hex.slice(3,5),16), b = parseInt(hex.slice(5,7),16);
    return (0.299*r + 0.587*g + 0.114*b) / 255 > 0.55 ? "#000" : "#fff";
  }

  // filteredCourts — inline filter on every render (line 416-420):
  const filteredCourts = searchName.trim().length >= 2
    ? (courts ?? []).filter(c => c.name.toLowerCase().includes(searchName.trim().toLowerCase())).slice(0, 7)
    : [];

  // ALL city derivations inline every render (lines 422-434):
  const uniqueCities = [...new Set((courts ?? []).map(c => c.city).filter((c): c is string => !!c))].sort();
  const cityCounts = (courts ?? []).reduce<Record<string, number>>((acc, c) => { ... }, {});
  const popularCities = [...uniqueCities].sort((a,b) => ...).slice(0, 5);
  const otherCities = uniqueCities.filter(c => !popularCities.includes(c));
  const filteredPopular = popularCities.filter(c => !cityFilter || c.toLowerCase().includes(cityFilter));
  const filteredOther = otherCities.filter(c => !cityFilter || c.toLowerCase().includes(cityFilter));
}
```

